package com.bridger.momentum;
import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Minute aggregates: no replay frames or per-attempt disk files. Worker-thread only. */
public final class BridgeStats {
 public enum Period{ALL_TIME("All time"),TODAY("Today"),THIS_WEEK("This week"),LAST_30_DAYS("Last 30 days");public final String label;Period(String label){this.label=label;}}
 public static final class Totals{
  public long attempts,successes,jumps;public double sum,squared,best=Double.POSITIVE_INFINITY,worst;
  void add(Totals b){attempts+=b.attempts;successes+=b.successes;jumps+=b.jumps;sum+=b.sum;squared+=b.squared;best=Math.min(best,b.best);worst=Math.max(worst,b.worst);}
  public double average(){return successes==0?Double.NaN:sum/successes;}
  public double rate(){return attempts==0?Double.NaN:100.0*successes/attempts;}
  public double deviation(){return successes==0?Double.NaN:Math.sqrt(Math.max(0,squared/successes-average()*average()));}
 }
 private static final class Bucket{final String server,mode;final long minute;final Totals totals=new Totals();Bucket(String server,String mode,long minute){this.server=server;this.mode=mode;this.minute=minute;}}
 public static final class Point{public final String label;public final Totals totals;Point(String label,Totals totals){this.label=label;this.totals=totals;}}
 public static final class View{public final Totals totals;public final List<Point> points;public final List<String> servers;public final long since;public final boolean imported;View(Totals totals,List<Point> points,List<String> servers,long since,boolean imported){this.totals=totals;this.points=Collections.unmodifiableList(points);this.servers=Collections.unmodifiableList(servers);this.since=since;this.imported=imported;}}
 private final Map<String,Bucket> buckets=new HashMap<>();public long since,revision;public boolean imported;public final Set<String> historicalIds=new HashSet<>();
 public BridgeStats(long since){this.since=since;}
 public void record(String server,ServerMode.Mode mode,long time,boolean success,double seconds,int jumps){
  if(!Double.isFinite(seconds)||seconds<0||success&&seconds>86400||time<0||jumps<0)throw new IllegalArgumentException("Invalid run statistics");
  server=PresetServers.canonical(server);if(server.isEmpty())server="Unknown server";long minute=time/60000;String key=key(server,mode.name(),minute);Bucket b=buckets.get(key);if(b==null){if(buckets.size()>=200000)throw new IllegalStateException("Statistics bucket limit reached");b=new Bucket(server,mode.name(),minute);buckets.put(key,b);}Totals t=b.totals;t.attempts++;t.jumps+=jumps;if(success){t.successes++;t.sum+=seconds;t.squared+=seconds*seconds;t.best=Math.min(t.best,seconds);t.worst=Math.max(t.worst,seconds);}revision++;
 }
 private static String key(String server,String mode,long minute){return minute+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(server.getBytes(java.nio.charset.StandardCharsets.UTF_8))+"."+mode;}
 public View view(String server,ServerMode.Mode mode,Period period,Instant now,ZoneId zone){
  LocalDate today=now.atZone(zone).toLocalDate(),start=period==Period.TODAY?today:period==Period.THIS_WEEK?today.minusDays(today.getDayOfWeek().getValue()-1):period==Period.LAST_30_DAYS?today.minusDays(29):Instant.ofEpochMilli(since).atZone(zone).toLocalDate();
  if(period==Period.ALL_TIME)for(Bucket b:buckets.values()){LocalDate date=Instant.ofEpochMilli(b.minute*60000).atZone(zone).toLocalDate();if(date.isBefore(start))start=date;}
  long first=Long.MAX_VALUE,last=Long.MIN_VALUE;LocalDate firstDate=null,lastDate=null;
  for(Bucket b:buckets.values()){if(!server.isEmpty()&&!server.equals(b.server)||mode!=null&&!mode.name().equals(b.mode))continue;LocalDate d=Instant.ofEpochMilli(b.minute*60000).atZone(zone).toLocalDate();if(d.isBefore(start)||d.isAfter(today)||b.minute>now.toEpochMilli()/60000)continue;first=Math.min(first,b.minute);last=Math.max(last,b.minute);if(firstDate==null||d.isBefore(firstDate))firstDate=d;if(lastDate==null||d.isAfter(lastDate))lastDate=d;}
  boolean intraday=firstDate!=null&&firstDate.equals(lastDate);long minuteStep=intraday?Math.max(1,(last-first+60)/60):1;
  long days=Math.max(1,java.time.temporal.ChronoUnit.DAYS.between(start,today)+1),step=Math.max(1,(days+29)/30);Totals total=new Totals();TreeMap<Long,Totals> points=new TreeMap<>();TreeSet<String> servers=new TreeSet<>();
  for(Bucket b:buckets.values()){servers.add(b.server);if(!server.isEmpty()&&!server.equals(b.server)||mode!=null&&!mode.name().equals(b.mode))continue;ZonedDateTime date=Instant.ofEpochMilli(b.minute*60000).atZone(zone);if(date.toLocalDate().isBefore(start)||date.toLocalDate().isAfter(today)||b.minute>now.toEpochMilli()/60000)continue;total.add(b.totals);long index=intraday?(b.minute-first)/minuteStep:java.time.temporal.ChronoUnit.DAYS.between(start,date.toLocalDate())/step;points.computeIfAbsent(index,k->new Totals()).add(b.totals);}
  List<Point> series=new ArrayList<>();int count=intraday?(int)((last-first)/minuteStep+1):(int)((days+step-1)/step);for(int i=0;i<count;i++){String label=intraday?Instant.ofEpochMilli((first+i*minuteStep)*60000).atZone(zone).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm")):start.plusDays(i*step).toString().substring(5);series.add(new Point(label,points.getOrDefault((long)i,new Totals())));}return new View(total,series,new ArrayList<>(servers),since,imported);
 }
 public void write(Path file)throws IOException{Properties p=new Properties();p.setProperty("version","2");p.setProperty("since",Long.toString(since));p.setProperty("imported",Boolean.toString(imported));for(String id:historicalIds)p.setProperty("seen."+id,"1");for(Map.Entry<String,Bucket> e:buckets.entrySet()){Totals t=e.getValue().totals;p.setProperty("bucket."+e.getKey(),t.attempts+","+t.successes+","+t.sum+","+t.squared+","+t.best+","+t.worst+","+t.jumps);}Files.createDirectories(file.toAbsolutePath().getParent());Path temp=Files.createTempFile(file.toAbsolutePath().getParent(),"stats-",".part");try{try(OutputStream out=Files.newOutputStream(temp)){p.store(out,"BridgeTap local minutely statistics");}Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temp);}}
 public static BridgeStats read(Path file,long now)throws IOException{BridgeStats stats=new BridgeStats(now);if(!Files.exists(file))return stats;if(Files.size(file)>32*1024*1024)throw new IOException("Statistics file exceeds size limit");Properties p=new Properties();try(InputStream in=Files.newInputStream(file)){p.load(in);}try{boolean legacy="1".equals(p.getProperty("version"));if(!legacy&&!"2".equals(p.getProperty("version")))throw new IllegalArgumentException("Unsupported statistics version");stats.since=Long.parseLong(p.getProperty("since"));stats.imported=Boolean.parseBoolean(p.getProperty("imported","false"));for(String key:p.stringPropertyNames())if(key.startsWith("seen.")){String id=key.substring(5);if(!id.matches("[a-f0-9-]{36}")||stats.historicalIds.size()>=100000)throw new IllegalArgumentException("Invalid historical sample ID");stats.historicalIds.add(id);}else if(key.startsWith("bucket.")){String[] id=key.substring(7).split("\\."),values=p.getProperty(key).split(",");if(id.length!=3||values.length!=7||stats.buckets.size()>=200000)throw new IllegalArgumentException("Invalid statistics bucket");ServerMode.Mode.valueOf(id[2]);Bucket b=new Bucket(new String(Base64.getUrlDecoder().decode(id[1]),java.nio.charset.StandardCharsets.UTF_8),id[2],Math.multiplyExact(Long.parseLong(id[0]),legacy?60:1));Totals t=b.totals;t.attempts=Long.parseLong(values[0]);t.successes=Long.parseLong(values[1]);t.sum=Double.parseDouble(values[2]);t.squared=Double.parseDouble(values[3]);t.best=Double.parseDouble(values[4]);t.worst=Double.parseDouble(values[5]);t.jumps=Long.parseLong(values[6]);if(b.minute<0||b.minute>253402300799000L/60000||stats.since<0||stats.since>253402300799000L||t.attempts<0||t.successes<0||t.successes>t.attempts||!Double.isFinite(t.sum)||!Double.isFinite(t.squared)||t.sum<0||t.squared<0||t.jumps<0||Double.isNaN(t.best)||t.worst<0||!Double.isFinite(t.worst)||(t.successes>0&&(!Double.isFinite(t.best)||t.best<0)))throw new IllegalArgumentException("Invalid statistics values");stats.buckets.put(key(b.server,b.mode,b.minute),b);}return stats;}catch(IllegalArgumentException|ArithmeticException ex){throw new IOException("Invalid statistics file",ex);}}
}
